        public Input<string>? Subscription { get; set; }

        /// <summary>
        /// ID of the test clock this subscription schedule belongs to.
        /// </summary>
        [Input("testClock")]
        public Input<string>? TestClock { get; set; }

        public SubscriptionScheduleState()
        {
        }
        public static new SubscriptionScheduleState Empty => new SubscriptionScheduleState();
    }
}
